<template>
 <div class="app-container purchase-returns">
  <el-alert title="采购退仓按原入库来源执行。出库、库存、供应商收货及款项分别跟踪。" type="info" :closable="false"/>
  <el-form class="filters" inline size="small" @submit.native.prevent="search">
   <el-form-item label="退仓单号"><el-input v-model.trim="query.return_sn" clearable placeholder="完整CGT单号"/></el-form-item><el-form-item label="原采购单号"><el-input v-model.trim="query.po_sn" clearable/></el-form-item><el-form-item label="仓库交互状态"><el-select v-model="query.dispatch_state" clearable><el-option v-for="(label,key) in dispatch" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item>
  </el-form>
  <p class="muted">默认查询近90天；完整退仓单号或原采购单号可跨日期定位。</p><div class="quick-filters"><el-radio-group v-model="query.quick" size="small" @change="search"><el-radio-button v-for="(label,key) in filters" :key="key" :label="key">{{label}}</el-radio-button></el-radio-group></div>
  <div class="toolbar"><el-button v-hasPermi="['warehouse:purchaseReturn:create']" size="small" type="primary" @click="newReturn">新增采购退仓</el-button><el-button size="small" @click="load">刷新列表</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <el-table :data="rows" v-loading="loading" size="small" empty-text="当前筛选范围没有采购退仓单">
   <el-table-column label="退仓单 / 原采购" min-width="290"><template slot-scope="{row}"><el-button type="text" @click="show(row.id)">{{row.return_sn}}</el-button><div><router-link class="muted" :to="{path:'/oms-supplychain/poInfo',query:{purchaseId:row.purchase_id}}">{{row.po_sn}}</router-link></div></template></el-table-column>
   <el-table-column label="供应商 / 出库虚仓" min-width="210"><template slot-scope="{row}">{{row.supplier_name}}<div class="muted">{{row.store_code}}</div></template></el-table-column>
   <el-table-column label="当前进度 / 待办" min-width="260"><template slot-scope="{row}"><el-tag size="mini" :type="tone(row)">{{row.progress_label||states[row.state]}}</el-tag><div class="muted">{{row.last_error||row.progress_hint}}</div></template></el-table-column>
   <el-table-column label="数量进度" min-width="200"><template slot-scope="{row}">申请 {{units('quantity',row)}}<div>实出 {{units('accepted_quantity',row)}} · 未出 {{units('remaining',row)}}</div><div class="muted">库存已扣 {{units('posted_quantity',row)}} · 占用 {{units('held',row)}}</div></template></el-table-column>
   <el-table-column v-if="rows.some(r=>Number(r.fulfillment_model)===2)" label="执行 / 包裹" min-width="170"><template slot-scope="{row}"><template v-if="Number(row.fulfillment_model)===2">{{row.execution_count||0}} 次执行 · {{row.parcel_count||0}} 个包裹<div class="muted">{{row.parcel_pending||0}} 个包裹待核对</div><div v-if="row.parcel_unknown_execution_count" class="muted">{{row.parcel_unknown_execution_count}} 次执行尚无包裹明细</div><div v-if="row.continuation_state" class="muted">{{row.continuation_state==='REVIEW'?'恢复待审核':'继续待确认原执行'}}</div></template><span v-else>—</span></template></el-table-column>
   <el-table-column label="仓库最近交互" min-width="200"><template slot-scope="{row}">{{row.warehouseLabel||dispatch[row.dispatch_state]}}<template v-if="row.latestInteraction&&row.latestInteraction.id"><div>{{logActions[row.latestInteraction.action]||row.latestInteraction.action}} · {{logResults[row.latestInteraction.result]||row.latestInteraction.result}}</div><div class="muted">{{row.latestInteraction.create_time}}</div></template></template></el-table-column>
   <el-table-column label="供应商款项凭证" min-width="155"><template slot-scope="{row}">{{fundStates[row.funds_state]||row.funds_state}}<div class="muted">已登记 ¥{{money(row.funds_amount)}}<br>剩余待核对 ¥{{money(row.funds_remaining)}}</div><span v-if="row.funds_over_recorded" class="danger">收回后金额需核对</span></template></el-table-column>
   <el-table-column label="操作" fixed="right" width="145"><template slot-scope="{row}"><el-button type="text" @click="show(row.id)">查看详情</el-button><div><el-button v-if="row.primary_action" v-hasPermi="actionPermissions(row.primary_action)" type="text" @click="openPrimary(row)">{{primaryLabel(row)}}</el-button></div></template></el-table-column>
  </el-table><pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" :page-sizes="[20,50,100]" @pagination="load"/>
  <purchase-return-create :visible.sync="creating" :purchase-id="createPurchaseId" @created="createdReturn"/>
  <el-drawer :visible.sync="visible" title="采购退仓详情" size="94%" append-to-body>
   <div v-loading="detailLoading" class="return-detail">
    <el-alert v-if="detailError" :title="detailError" type="error" :closable="false"/>
    <template v-if="detail">
     <header><div><h2>{{detail.return_sn}}</h2><p>{{detail.supplier_name}} · {{detail.store_code}}</p></div><el-button size="small" @click="show(detail.id)">刷新详情</el-button></header>
     <section class="progress" :class="{warning:['REMAINING','REVIEW','POSTING','UNKNOWN'].includes(detail.progress_code)}"><strong>{{detail.progress_label}}</strong><p>{{detail.progress_hint}}</p><p v-if="detail.progress_code==='REMAINING'">申请 {{units('quantity')}}，仓库最终实出 {{units('accepted_quantity')}}，库存已扣 {{units('posted_quantity')}}；剩余 {{units('remaining')}} 未出库。</p><el-alert v-if="detail.last_error" :title="detail.last_error" type="warning" :closable="false"/>
      <div class="metrics"><article v-for="m in metrics" :key="m.key"><span>{{m.label}}</span><strong>{{units(m.key)}}</strong></article></div>
      <div v-if="detail.stock_query_error" class="danger">{{detail.stock_query_error}}，占用数量暂未确认。</div>
      <div class="toolbar">
       <el-button v-if="detail.state==='DRAFT'" v-hasPermi="['warehouse:purchaseReturn:approve']" type="primary" size="small" :loading="busy" @click="act('approve')">审核并自动退仓</el-button>
       <el-button v-if="detail.primary_action==='remaining'" v-hasPermi="['warehouse:purchaseReturn:cancel','warehouse:purchaseReturn:continue']" type="primary" size="small" @click="followup('REMAINING')">{{Number(detail.fulfillment_model)===2?'同单继续退剩余数量':'处理剩余数量'}}</el-button>
       <el-button v-if="detail.primary_action==='retry'" v-hasPermi="['warehouse:purchaseReturn:retry']" type="primary" size="small" :loading="busy" @click="act('retry')">{{primaryLabel(detail)}}</el-button>
       <el-button v-if="detail.primary_action==='logs'" v-hasPermi="['warehouse:wms:log']" size="small" @click="openLog(0)">核对异常回传</el-button>
       <el-button v-if="Number(detail.outbound_mode)===1&&!['DRAFT','APPROVING'].includes(detail.state)&&!['UNSENT','PENDING','SENDING'].includes(detail.dispatch_state)" v-hasPermi="['warehouse:purchaseReturn:queryWarehouse']" size="small" :loading="busy" @click="act('query')">查询原仓库单</el-button>
       <el-button v-if="!['CANCELED','COMPLETED'].includes(detail.state)&&(detail.primary_action!=='remaining'||Number(detail.fulfillment_model)===2)" v-hasPermi="['warehouse:purchaseReturn:cancel']" size="small" :disabled="!!detail.receipt_review_pending||detail.accepted_quantity>detail.posted_quantity" @click="detail.state==='DRAFT'?act('cancel'):followup('STOP')">{{detail.state==='DRAFT'?'取消申请':'申请停止剩余退仓'}}</el-button>
       <el-button v-if="detail.progress_code==='PARTIAL_CLOSED'&&!detail.child_returns.length&&!detail.continuation_state&&!(detail.execution_requests||[]).some(r=>r.state==='REVIEW')" v-hasPermi="['warehouse:purchaseReturn:continue']" size="small" @click="followup('REMAINING')">{{Number(detail.fulfillment_model)===2?'申请恢复已释放余量':'继续退剩余数量'}}</el-button>
      </div>
     </section>
     <el-descriptions border :column="3" size="small"><el-descriptions-item label="原采购"><router-link :to="{path:'/oms-supplychain/poInfo',query:{purchaseId:detail.purchase_id}}">{{detail.po_sn}}</router-link></el-descriptions-item><el-descriptions-item label="仓库受理">{{dispatch[detail.dispatch_state]}}</el-descriptions-item><el-descriptions-item label="仓库原单号">{{detail.external_order||'尚无'}}</el-descriptions-item><el-descriptions-item label="供应商收件人">{{detail.receiver.name}} · {{detail.receiver.mobile}}</el-descriptions-item><el-descriptions-item label="供应商收货地址" :span="2">{{detail.receiver.province}} {{detail.receiver.city}} {{detail.receiver.area}} {{detail.receiver.detailAddress}}</el-descriptions-item><el-descriptions-item label="原采购预计退仓货值">¥{{money(detail.planned_amount)}}</el-descriptions-item><el-descriptions-item label="实际出库采购货值">¥{{money(detail.posted_amount)}}</el-descriptions-item><el-descriptions-item label="退仓依据">{{detail.reason}}</el-descriptions-item></el-descriptions>
     <div v-if="detail.parent_return.length||detail.child_returns.length||detail.continuation_state==='WAIT_RELEASE'" class="relations"><span v-for="p in detail.parent_return" :key="'p'+p.id">承接原退仓 <el-button type="text" @click="show(p.id)">{{p.return_sn}}</el-button></span><span v-for="c in detail.child_returns" :key="'c'+c.id">关联后续退仓 <el-button type="text" @click="show(c.id)">{{c.return_sn}}</el-button> · 须独立审核</span><span v-if="detail.continuation_state==='WAIT_RELEASE'">后续申请已提交，等待原占用释放或草稿生成，请刷新进度。</span></div>
     <purchase-return-fulfillment v-if="Number(detail.fulfillment_model)===2" ref="fulfillment" :detail="detail" @changed="refreshDetail" @reclaim="showReclaim"><template slot="funds"><el-alert v-if="detail.funds_over_recorded" title="已有登记金额超过收回后的净退仓货值，请核对原凭证并按实际情况冲销或更正。系统没有自动划转资金。" type="warning" :closable="false"/><div class="money-summary"><article><span>实际出库采购货值</span><strong>¥{{money(detail.posted_amount)}}</strong></article><article><span>拒收收回货值</span><strong>¥{{money(detail.recovered_amount)}}</strong></article><article><span>净退仓货值 / 已登记</span><strong>¥{{money(detail.net_posted_amount)}} / ¥{{money(detail.funds_amount)}}</strong></article><article><span>剩余待核对凭证</span><strong>¥{{money(detail.funds_remaining)}}</strong></article></div><div class="toolbar"><el-button v-if="Number(detail.funds_remaining)>0" v-hasPermi="['warehouse:purchaseReturn:funds']" type="primary" size="small" @click="followup('FUNDS')">登记退款 / 抵扣凭证</el-button><span class="muted">支持多笔凭证；冲销追加记录并保留原凭证，登记不执行银行付款。</span></div><el-table :data="detail.funds" size="small" empty-text="尚未登记款项凭证"><el-table-column prop="id" label="凭证记录" width="100"/><el-table-column label="类型"><template slot-scope="{row}">{{row.kind==='REVERSAL'?'冲销凭证':row.kind==='REFUND'?'退款凭证':'抵扣凭证'}}<div v-if="row.original_id" class="muted">原凭证 #{{row.original_id}}</div><div v-if="row.reversed_by" class="muted">已由 #{{row.reversed_by}} 冲销</div></template></el-table-column><el-table-column label="金额"><template slot-scope="{row}">¥{{money(row.amount)}}</template></el-table-column><el-table-column prop="evidence" label="凭证与核对依据" min-width="280"/><el-table-column prop="actor" label="登记人" width="120"/><el-table-column prop="create_time" label="时间" width="180"/><el-table-column label="操作" width="110"><template slot-scope="{row}"><el-button v-if="row.kind!=='REVERSAL'&&!row.reversed_by" v-hasPermi="['warehouse:purchaseReturn:funds']" type="text" @click="followup('REVERSAL',row)">冲销更正</el-button></template></el-table-column></el-table></template></purchase-return-fulfillment>
     <el-tabs v-else v-model="tab">
      <el-tab-pane label="商品与来源" name="lines"><el-table :data="detail.lines" size="small"><el-table-column label="实际商品 / 原入库" min-width="280"><template slot-scope="{row}"><strong>{{row.goods_name}}</strong><div class="muted">{{row.sku_sn}}<br>{{row.ticket_sn}} · {{row.source_key}}</div></template></el-table-column><el-table-column label="原批次 / 质量" min-width="170"><template slot-scope="{row}">{{row.batch_code}}<div>{{row.inventory_type==='ZP'?'正品':'次品'}}</div></template></el-table-column><el-table-column label="申请 / 实出 / 已扣账" min-width="180"><template slot-scope="{row}">{{row.quantity}} / {{row.accepted_quantity}} / {{row.posted_quantity}} {{row.stock_unit}}</template></el-table-column><el-table-column label="未出库 / 已停止" min-width="160"><template slot-scope="{row}">{{Number(row.quantity)-Number(row.accepted_quantity)}} / {{detail.state==='CANCELED'?Number(row.quantity)-Number(row.posted_quantity):0}} {{row.stock_unit}}</template></el-table-column><el-table-column label="原采购单价"><template slot-scope="{row}">¥{{money(row.purchase_price)}}</template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="仓库与物流" name="warehouse"><p class="muted">仓库受理、实际出库、最终确认分别保留。物流展示对应仓库实际出库回传。</p><el-timeline><el-timeline-item v-for="e in detail.events" :key="e.id" :timestamp="e.create_time" :type="e.state==='POSTED'?'success':'warning'"><strong>{{e.receipt.complete?'仓库最终确认':'仓库分批出库'}} · 本次 {{eventUnits(e)}}</strong><p>{{e.receipt.carrier_name||e.receipt.carrier_code||'仓库未提供快递名称'}} · {{e.receipt.waybill||'仓库未提供运单'}} · {{e.state==='POSTED'?'库存已扣账':e.state==='FAILED'?'库存扣账失败':'库存待扣账'}}</p><div v-for="(p,i) in e.receipt.packages||[]" :key="i" class="muted">{{p.carrier_name||p.carrier_code}} · {{p.waybill}} · {{p.package_code}}</div><el-button v-if="e.source_log_id" v-hasPermi="['warehouse:wms:log']" type="text" @click="openLog(e.source_log_id)">查看原出库回传</el-button><div class="danger">{{e.last_error}}</div></el-timeline-item></el-timeline><el-empty v-if="!detail.events.length" description="尚未收到实际出库回传"/><el-button v-hasPermi="['warehouse:wms:log']" size="small" @click="tab='logs'">查看下发、查询与停止交互</el-button></el-tab-pane>
      <el-tab-pane label="库存记录" name="stock"><el-alert v-if="detail.stock_query_error" :title="detail.stock_query_error" type="error" :closable="false"/><el-table :data="stockRows" size="small" empty-text="尚未确认库存锁定"><el-table-column label="实际SKU / 原批次" min-width="280"><template slot-scope="{row}">{{row.sku_sn}}<div class="muted">{{row.batch_code}} · {{row.inventory_type==='ZP'?'正品':'次品'}}</div></template></el-table-column><el-table-column prop="quantity" label="原占用"/><el-table-column prop="consumed_quantity" label="已出库扣减"/><el-table-column prop="released_quantity" label="已释放"/><el-table-column label="剩余占用"><template slot-scope="{row}">{{Number(row.quantity)-Number(row.consumed_quantity)-Number(row.released_quantity)}}</template></el-table-column><el-table-column prop="recovered_quantity" label="拒收后独立收回"/></el-table><p class="muted">来源单号 {{detail.return_sn}}。收回入库追加新库存流水，原出库数量和原采购累计实收保留。</p><el-table :data="detail.events" size="small"><el-table-column prop="message_id" label="原出库事件" min-width="260"/><el-table-column label="对应实出数量"><template slot-scope="{row}">{{eventUnits(row)}}</template></el-table-column><el-table-column label="扣账结果"><template slot-scope="{row}">{{row.state==='POSTED'?'扣账成功':row.state==='FAILED'?'扣账失败':'等待扣账'}}<div class="danger">{{row.last_error}}</div></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="供应商收货与收回" name="supplier"><div class="supplier-summary"><span>已签收 <b>{{units('supplier_received_quantity')}}</b></span><span>已拒收 <b>{{units('supplier_refused_quantity')}}</b></span><span>尚未确认 <b>{{units('supplier_pending')}}</b></span></div><div class="toolbar"><el-button v-if="Number(detail.posted_quantity)>0" v-hasPermi="['warehouse:purchaseReturn:supplierReceipt']" size="small" type="primary" @click="followup('SUPPLIER')">登记签收 / 拒收 / 短收</el-button><el-button v-if="detail.lines.some(l=>Number(l.supplier_refused_quantity)>Number(l.reclaim_claimed_quantity||0))" v-hasPermi="['warehouse:purchaseReturn:reclaimCreate']" size="small" @click="followup('RECLAIM')">创建拒收收回入库</el-button></div><el-table :data="detail.lines" size="small"><el-table-column prop="sku_sn" label="实际SKU" min-width="250"/><el-table-column label="实际退仓 / 已签收 / 已拒收"><template slot-scope="{row}">{{row.posted_quantity}} / {{row.supplier_received_quantity}} / {{row.supplier_refused_quantity}} {{row.stock_unit}}</template></el-table-column><el-table-column label="已安排收回 / 已收回入账"><template slot-scope="{row}">{{row.reclaim_claimed_quantity||0}} / {{row.recovered_quantity||0}} {{row.stock_unit}}</template></el-table-column></el-table><h3>供应商收货凭证</h3><el-table :data="detail.supplier_receipts" size="small"><el-table-column label="登记结果" width="140"><template slot-scope="{row}">{{supplierResults[row.decision]}}</template></el-table-column><el-table-column label="逐行数量" min-width="220"><template slot-scope="{row}"><div v-for="l in row.lines" :key="l.line_id">{{lineName(l.line_id)}} · {{l.quantity}} {{lineUnit(l.line_id)}}</div></template></el-table-column><el-table-column prop="evidence" label="凭证与核对依据" min-width="260"/><el-table-column prop="actor" label="登记人" width="120"/><el-table-column prop="create_time" label="时间" width="180"/></el-table><h3>关联拒收收回入库单</h3><el-table :data="detail.reclaims" size="small" empty-text="尚未创建拒收收回入库单"><el-table-column label="收回单号" min-width="290"><template slot-scope="{row}"><el-button type="text" @click="$refs.reclaim.show(row.id)">{{row.reclaim_sn}}</el-button></template></el-table-column><el-table-column label="进度"><template slot-scope="{row}">{{reclaimStates[row.state]}}<div class="muted">{{dispatch[row.dispatch_state]}}</div></template></el-table-column><el-table-column label="计划 / 实收 / 已入账"><template slot-scope="{row}">{{row.quantity}} / {{row.accepted_quantity}} / {{row.posted_quantity}}<div class="muted">具体单位见收回明细</div></template></el-table-column><el-table-column label="供应商退回物流"><template slot-scope="{row}">{{row.carrier_code}} · {{row.waybill}}<div class="danger">{{row.last_error}}</div></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="供应商款项" name="funds"><el-alert v-if="detail.funds_over_recorded" title="已有登记金额超过收回后的净退仓货值，请核对原凭证并按实际情况冲销或更正。系统没有自动划转资金。" type="warning" :closable="false"/><div class="money-summary"><article><span>实际出库采购货值</span><strong>¥{{money(detail.posted_amount)}}</strong></article><article><span>拒收收回货值</span><strong>¥{{money(detail.recovered_amount)}}</strong></article><article><span>净退仓货值 / 已登记</span><strong>¥{{money(detail.net_posted_amount)}} / ¥{{money(detail.funds_amount)}}</strong></article><article><span>剩余待核对凭证</span><strong>¥{{money(detail.funds_remaining)}}</strong></article></div><div class="toolbar"><el-button v-if="Number(detail.funds_remaining)>0" v-hasPermi="['warehouse:purchaseReturn:funds']" type="primary" size="small" @click="followup('FUNDS')">登记退款 / 抵扣凭证</el-button><span class="muted">支持多笔凭证；冲销追加记录并保留原凭证，登记不执行银行付款。</span></div><el-table :data="detail.funds" size="small" empty-text="尚未登记款项凭证"><el-table-column prop="id" label="凭证记录" width="100"/><el-table-column label="类型"><template slot-scope="{row}">{{row.kind==='REVERSAL'?'冲销凭证':row.kind==='REFUND'?'退款凭证':'抵扣凭证'}}<div v-if="row.original_id" class="muted">原凭证 #{{row.original_id}}</div><div v-if="row.reversed_by" class="muted">已由 #{{row.reversed_by}} 冲销</div></template></el-table-column><el-table-column label="金额"><template slot-scope="{row}">¥{{money(row.amount)}}</template></el-table-column><el-table-column prop="evidence" label="凭证与核对依据" min-width="280"/><el-table-column prop="actor" label="登记人" width="120"/><el-table-column prop="create_time" label="时间" width="180"/><el-table-column label="操作" width="110"><template slot-scope="{row}"><el-button v-if="row.kind!=='REVERSAL'&&!row.reversed_by" v-hasPermi="['warehouse:purchaseReturn:funds']" type="text" @click="followup('REVERSAL',row)">冲销更正</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="仓库交互" name="logs" lazy><warehouse-interactions v-if="tab==='logs'&&Number(detail.outbound_mode)===1" ref="logs" :sn="detail.return_sn"/><el-empty v-else description="自动虚拟出库没有外部仓库交互"/></el-tab-pane>
      <el-tab-pane label="处理记录" name="audit" lazy><el-table :data="detail.audit" size="small"><el-table-column label="动作" width="185"><template slot-scope="{row}">{{auditLabels[row.action]||row.action}}</template></el-table-column><el-table-column prop="actor" label="处理人" width="130"/><el-table-column prop="reason" label="处理结果与依据" min-width="300"/><el-table-column prop="create_time" label="时间" width="180"/></el-table></el-tab-pane>
     </el-tabs>
    </template>
   </div>
  </el-drawer>
  <purchase-return-followup v-if="detail" ref="followup" :detail="detail" @changed="refreshDetail" @reclaim="showReclaim"/><purchase-reclaim-detail ref="reclaim" @changed="refreshDetail"/>
 </div>
</template>
<script>
import {listReturns,returnDetail,returnAction} from '@/api/purchase/returns'
import WarehouseInteractions from '../order/ReturnInteractionPanel'
import PurchaseReturnCreate from './PurchaseReturnCreate'
import PurchaseReturnFollowup from './PurchaseReturnFollowup'
import PurchaseReclaimDetail from './PurchaseReclaimDetail'
import PurchaseReturnFulfillment from './PurchaseReturnFulfillment'
import {actions as logActions,results as logResults} from '../warehouse/wmsLogLabels'
const empty=()=>({return_sn:'',po_sn:'',state:'',dispatch_state:'',quick:'',pageNum:1,pageSize:20})
export default{
 components:{PurchaseReturnFulfillment,WarehouseInteractions,PurchaseReturnCreate,PurchaseReturnFollowup,PurchaseReclaimDetail},
 data:()=>({logActions,logResults,query:empty(),rows:[],total:0,loading:false,error:'',sequence:0,detailSequence:0,visible:false,detail:null,detailLoading:false,detailError:'',tab:'lines',creating:false,createPurchaseId:null,busy:false,filters:{'':'全部',DRAFT:'待审核',WAITING:'等待出库',REMAINING:'剩余待处理',HOLD:'仍有占用',POSTING:'库存待扣账',UNKNOWN:'仓库结果不明',REVIEW:'回传待核对',FUNDS:'款项待核对',PARCEL:'包裹待补齐 / 核对',SUPPLIER:'供应商商品待确认',RESTORE:'已释放余量恢复待审核',ENDED:'已结束'},metrics:[{label:'申请退仓',key:'quantity'},{label:'仓库实出',key:'accepted_quantity'},{label:'库存已扣账',key:'posted_quantity'},{label:'未出库',key:'remaining'},{label:'剩余占用',key:'held'}],states:{DRAFT:'待审核',APPROVING:'库存锁定中',APPROVED:'仓库执行中',CANCELING:'停止剩余待确认',CANCELED:'已结束',COMPLETED:'原计划出库已扣账',ATTENTION:'待核对'},dispatch:{UNSENT:'尚未下发',PENDING:'等待下发',SENDING:'下发结果待确认',UNKNOWN:'受理结果待确认',ACCEPTED:'仓库已受理',FAILED:'下发失败',CANCELED:'仓库已停止',VIRTUAL:'自动虚拟执行'},fundStates:{UNRECORDED:'未登记凭证',REFUND:'已登记退款凭证',CREDIT:'已登记抵扣凭证',MIXED:'退款及抵扣凭证'},supplierResults:{ACCEPT:'确认签收',REFUSE:'确认拒收',SHORT:'短收待核对'},reclaimStates:{DRAFT:'待审核',ACTIVE:'收回执行中',CANCELING:'停止剩余待确认',CANCELED:'剩余已停止',COMPLETED:'已收回入账'},auditLabels:{CREATE:'创建草稿',APPROVE:'审核通过',OUTBOUND_ACCEPTED:'确认实际出库',CANCEL_REQUEST:'申请停止退仓',CANCEL_CONFIRMED:'剩余停止已确认',RETRY:'重试未完成步骤',FUNDS_RECORD:'登记款项凭证',FUNDS_REVERSAL:'冲销原凭证',CONTINUE_REQUEST:'申请继续退剩余',CONTINUE_CREATED:'关联后续草稿已生成',SUPPLIER_ACCEPT:'登记供应商签收',SUPPLIER_REFUSE:'登记供应商拒收',SUPPLIER_SHORT:'登记供应商短收',RECLAIM_CREATE:'创建拒收收回草稿',RECLAIM_APPROVE:'审核收回入库',RECLAIM_RECEIPT:'仓库确认实际收回',RECLAIM_CANCEL:'停止剩余收回',RECLAIM_RETRY:'重试收回步骤'}}),
 computed:{stockRows(){return this.detail&&this.detail.stock&&this.detail.stock.lines||[]}},
 created(){this.route()},watch:{'$route.query'(){if(this.$route.path==='/oms-supplychain/purchaseReturns')this.route()}},beforeDestroy(){this.sequence++;this.detailSequence++},
 methods:{
  async route(){this.query={...empty(),return_sn:this.$route.query.return_sn||'',po_sn:this.$route.query.po_sn||''};if(this.$route.query.purchaseId)this.query.purchase_id=this.$route.query.purchaseId;await this.load();if(this.$route.query.id)this.show(Number(this.$route.query.id));if(this.$route.query.reclaimId)this.$refs.reclaim.show(Number(this.$route.query.reclaimId));if(this.$route.query.create==='1')this.newReturn()},
  money(v){return Number(v||0).toFixed(2)},tone(d){return ['COMPLETED','PARTIAL_CLOSED'].includes(d.progress_code)?'success':['REMAINING','REVIEW','POSTING','UNKNOWN','DISPATCH_FAILED'].includes(d.progress_code)?'warning':'info'},
  units(key,document){const d=document||this.detail;if(!d)return '0';if(key==='held'&&d.stock_query_error)return '暂未确认';if(key==='held'&&Number(d.fulfillment_model)===2&&d.state==='APPROVING')return '锁定待确认';const total={};for(const l of d.lines||d.quantity_summary||[]){let q=Number(l[key]||0);if(key==='pending')q=Math.max(0,Number(l.accepted_quantity)-Number(l.posted_quantity));if(key==='remaining')q=Math.max(0,Number(l.quantity)-Number(l.accepted_quantity));if(key==='held')q=Number(d.fulfillment_model)===2&&d.stock&&d.stock.lines?d.stock.lines.filter(s=>Number(s.line_key)===Number(l.id)).reduce((v,s)=>v+Number(s.quantity)-Number(s.consumed_quantity)-Number(s.released_quantity),0):d.stock_reserved&&!['CANCELED','COMPLETED'].includes(d.state)?Math.max(0,Number(l.quantity)-Number(l.posted_quantity)):0;if(key==='supplier_pending')q=Math.max(0,Number(l.posted_quantity)-Number(l.supplier_received_quantity)-Number(l.supplier_refused_quantity));const unit=l.stock_unit||'件';total[unit]=(total[unit]||0)+q}return Object.keys(total).filter(k=>total[k]>0).map(k=>total[k]+' '+k).join(' + ')||'0'},
  eventUnits(event){const totals={};for(const l of event.receipt.lines||[]){const source=this.detail.lines.find(x=>Number(x.id)===Number(l.line_key));const unit=source&&source.stock_unit||'件';totals[unit]=(totals[unit]||0)+Number(l.quantity)}return Object.keys(totals).map(k=>totals[k]+' '+k).join(' + ')||'0'},lineName(id){const l=this.detail.lines.find(l=>Number(l.id)===Number(id));return l?l.sku_sn:'原行 '+id},lineUnit(id){const l=this.detail.lines.find(l=>Number(l.id)===Number(id));return l&&l.stock_unit||''},
  primaryLabel(d){if(d.primary_action==='approve')return '审核退仓';if(d.primary_action==='remaining')return '处理剩余数量';if(d.primary_action==='query')return '查询原仓单';if(d.primary_action==='logs')return '核对异常回传';if(d.progress_code==='POSTING')return '重试库存扣账';if(d.progress_code==='DISPATCH_FAILED')return '重试仓库下发';if(d.continuation_state==='WAIT_RELEASE')return '继续生成后续草稿';return '重试库存锁定'},actionPermissions(action){if(action==='remaining')return ['warehouse:purchaseReturn:cancel','warehouse:purchaseReturn:continue'];return [action==='logs'?'warehouse:wms:log':'warehouse:purchaseReturn:'+({remaining:'cancel',query:'queryWarehouse'}[action]||action)]},
  search(){this.query.pageNum=1;this.load()},reset(){this.query=empty();this.load()},async load(){const seq=++this.sequence;this.loading=true;this.error='';try{const r=(await listReturns(this.query)).data;if(seq===this.sequence){this.rows=r.rows;this.total=Number(r.total)}}catch(e){if(seq===this.sequence)this.error=e.message||'采购退仓加载失败'}finally{if(seq===this.sequence)this.loading=false}},
  async show(id){const seq=++this.detailSequence;this.visible=true;this.detailLoading=true;this.detailError='';try{const d=(await returnDetail(id)).data;if(seq===this.detailSequence){if(!this.detail||Number(this.detail.id)!==Number(d.id))this.tab='lines';this.detail=d}}catch(e){if(seq===this.detailSequence){this.detail=null;this.detailError=e.message||'采购退仓详情加载失败'}}finally{if(seq===this.detailSequence)this.detailLoading=false}},
  newReturn(){this.createPurchaseId=this.$route.query.purchaseId?Number(this.$route.query.purchaseId):null;this.creating=true},createdReturn(id){this.load();this.show(id)},refreshDetail(){if(this.detail)this.show(this.detail.id);this.load()},async openPrimary(row){await this.show(row.id);await this.$nextTick();if(!this.detail||Number(this.detail.id)!==Number(row.id))return;if(row.primary_action==='remaining')this.followup('REMAINING');else if(row.primary_action==='logs')this.openLog(0);else this.act(row.primary_action)},followup(kind,original){if(Number(this.detail.fulfillment_model)===2&&!['FUNDS','REVERSAL'].includes(kind))this.$refs.fulfillment.open(kind,original);else this.$refs.followup.open(kind==='STOP'?'REMAINING':kind,original)},showReclaim(id){this.$refs.reclaim.show(id)},
  async act(action){if(this.busy||!this.detail)return;const cmd={control_version:this.detail.control_version};try{if(action==='approve')await this.$confirm('审核后按原批次锁定 '+this.units('quantity')+'，并自动执行仓库退仓。确认已核对商品和供应商收货地址？','审核退仓');if(action==='cancel')cmd.reason=(await this.$prompt('填写取消草稿依据。','取消退仓申请',{inputValidator:v=>!!v&&v.trim().length>=2||'至少填写2字依据'})).value;this.busy=true;await returnAction(this.detail.id,action,cmd);await this.show(this.detail.id);this.load()}catch(e){if(e!=='cancel'&&e!=='close')this.$message.error(e.message||'操作未确认，请刷新原单')}finally{this.busy=false}},async openLog(id){if(Number(this.detail.fulfillment_model)===2){await this.$refs.fulfillment.openLog(id);return;}this.tab='logs';await this.$nextTick();if(this.$refs.logs)this.$refs.logs.show(id)}
 }
}
</script>
<style scoped>
.filters{margin:20px 0}.quick-filters{margin:16px 0}.quick-filters ::v-deep .el-radio-button{margin-bottom:6px}.toolbar,header{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:18px 0}.toolbar .el-button{margin:0}header{justify-content:space-between}.return-detail{padding:0 24px 35px}.return-detail h2{font-size:20px;overflow-wrap:anywhere}.progress{border:1px solid #dce7f2;border-radius:9px;padding:20px;margin:16px 0;background:#f8fbff}.progress>strong{font-size:19px}.progress.warning{border-color:#edcc93;background:#fffaf1}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:20px 0}.metrics article,.money-summary article{padding:16px;background:#f0f5fc;border-radius:7px}.metrics span,.money-summary span{display:block;font-size:12px;color:#72849c}.metrics strong{display:block;font-size:25px;margin-top:8px}.muted{color:#7a899d;font-size:12px;line-height:1.8;overflow-wrap:anywhere}.danger{color:#c74545;font-size:12px}.relations{background:#f3f7fc;border-radius:7px;padding:10px 16px;margin-top:16px;display:flex;gap:20px;flex-wrap:wrap}.return-detail .el-tabs{margin-top:24px}.supplier-summary{display:flex;gap:32px;background:#f3f7fc;padding:18px;border-radius:7px}.money-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.money-summary strong{display:block;font-size:19px;margin-top:10px}.purchase-returns ::v-deep .cell{overflow-wrap:anywhere}.purchase-returns ::v-deep .el-button--text{white-space:normal;text-align:left}.el-alert{margin:12px 0}@media(max-width:1000px){.metrics,.money-summary{grid-template-columns:repeat(2,1fr)}.supplier-summary{flex-wrap:wrap}}
</style>
